var animating = !1, submitPhase1 = 0, submitPhase2 = 0, logoutPhase1 = 0,
  $login = document.querySelector(".login"),
  $status = document.querySelector("#status"),
  $loginSubmit = document.querySelector(".login-submit"),
  $logoutSubmit = document.querySelector(".logout-submit"),
  loggedIn = !1, intervalStatus = !1;

/* ===== حفظ آخر كرت مستخدم واستبدال القديم بالجديد ===== */
function saveHotLastUsername(username) {
  username = (username || "").trim();
  if (!username) return;

  try {
    localStorage.setItem("hot_last_username", username);
  } catch(e) {}

  try {
    document.cookie = "hot_last_username=" + encodeURIComponent(username) + "; path=/; max-age=" + (30 * 24 * 60 * 60);
  } catch(e) {}
}

function pop(e, t) {
  document.getElementById("popupMessage").innerText = e,
  document.getElementById("popupError").style.display = "flex",
  1 == t ? document.getElementById("err").style.display = "none"
         : document.getElementById("err").style.display = "block"
}

function onLoginSubmitted() {
  // تحقق من خانة الكرت
  const err = document.getElementById('error');
  const card = document.login.username.value.trim();

  if (!card) {
    err.innerText = 'يجب ادخال قيمة صحيحة!';
    showErrorPopup();
    return;
  }

  // نحفظ الكرت الجديد مباشرة ونستبدل القديم
  saveHotLastUsername(card);

  $loginSubmit.classList.add('processing');

  // عيّن سرعة افتراضية واكمل الدخول
  currentSpeedClass = 'speed_normal';   // غيّرها إذا تحتاج
  userLogin();                          // لا نفتح #chose-speed
}

function closePopup(e) {
  "popupError" === e.target.id && (document.getElementById("popupError").style.display = "none")
}

function showParentElement(e, t) {
  e.classList.add("success"),
  setTimeout(function () {
    t.style.display = "block",
    getComputedStyle(t).top,
    t.classList.add("active")
  }, submitPhase2 - 70),
  setTimeout(function () {
    hideLoginPage(),
    animating = !1,
    e.classList.remove("success", "processing")
  }, submitPhase2)
}

function hideLoginPage() {
  $login.style.display = "none",
  $login.classList.add("inactive")
}

function showLoginPage() {
  $login.style.display = "block",
  getComputedStyle($login).top,
  $login.classList.remove("inactive")
}

function initHotspotEvents(e, t) {
  var n, i = t.querySelectorAll(".app-logout");
  for (n in e.addEventListener("click", function () {
    animating || (animating = !0, this.classList.add("processing"), showParentElement(this, t))
  }), i) {
    var o = i[n];
    "object" == typeof o && o.addEventListener("click", function () {
      if (!animating) {
        animating = !0;
        var n = this;
        setTimeout(function () {
          t.classList.remove("active"),
          showLoginPage()
        }, submitPhase2 + 120),
        setTimeout(function () {
          t.style.display = "none",
          animating = !1,
          n.classList.remove("processing")
        }, submitPhase2)
      }
    })
  }
}

function toArabicTime(e) {
  var t = e, n = "", i = "", o = "", s = "";
  if ("" === e) return "";
  if (0 <= e.indexOf("d")) {
    t = e.split("d");
    n = "" !== t[0] ? t[0] + " يوم " : "";
    t = t[1]
  }
  if (0 <= t.indexOf("h")) {
    t = t.split("h");
    i = "" !== t[0] ? t[0] + " ساعة " : "";
    t = t[1]
  }
  if (0 <= t.indexOf("m")) {
    t = t.split("m");
    o = "" !== t[0] ? t[0] + " دقيقة " : "";
    t = t[1]
  }
  if (0 <= t.indexOf("s")) {
    t = t.split("s");
    s = "" !== t[0] ? t[0] + " ثانية " : ""
  }
  return n + i + o + s
}

function toArabicBytes(e) {
  if (isNaN(e) || !isFinite(e)) return "";
  return e < 1024
    ? e + " بايت "
    : e < 1048576
      ? Math.round(e / 1024) + " كيلوبايت "
      : e < 1073741824
        ? Math.round(e / 1048576) + " ميجابايت "
        : (e / (1000 * 1000 * 1000)).toFixed(2) + " جيجابايت ";
}

function getLoginCardCooki() {
  var e = { username: "", speed: "", password: "" };
  return document.cookie.split(";").forEach(function (t) {
    e[(t = t.trim().split("="))[0]] = t[1]
  }), e
}

function toArabicError(e) {
  var t, n = {
    "user&not found": "لقد ادخلت الكرت بطريقة غير صحيحة، الرجاء المحاولة مرة اخرى",
    "simultaneous session limit reached|no more sessions are allowed": "المعذرة ، هذا الكرت مستخدم حالياً في جهاز آخر",
    "invalid password": "تاكد من كتابة كلمة المرور بشكل صحيح",
    "uptime limit reached|No more online time|uptime limit": "عذراً لقد انتهى الوقت المتاح لك",
    "traffic limit|transfer limit reached": "لقد انتهى رصيد هذا الكرت",
    "invalid username or password|not found": "لقد ادخلت اسم المستخدم بطريقة غير صحيحة، الرجاء المحاولة مرة اخرى",
    "no valid profile found": "لقد انتهت صلاحية هذا الكرت",
    "invalid Calling-Station-Id": "هذا الكرت مقترن بجهاز آخر!",
    "server&is&not&responding": "يرجى الانتظار، يتم الآن اعادة تشغيل الشبكة، هذه العملية قد تستغرق بعض الوقت",
    "web&browser&did&not&send": "يرجى محاولة ادخال الكرت مرة اخرى"
  }, i = "حصل خطأ: " + e;

  for (t in n) {
    var o = n[t];

    if (t.indexOf("&") > -1) {
      for (var s = t.split("&"), a = !0, r = 0; r < s.length; r++) {
        if (-1 === e.indexOf(s[r])) {
          a = !1;
          break;
        }
      }

      if (a) {
        i = o;
        break;
      }

    } else if (t.indexOf("|") > -1) {
      for (var l = t.split("|"), u = 0; u < l.length; u++) {
        if (e.indexOf(l[u]) > -1) {
          i = o;
          break;
        }
      }

    } else if (e.indexOf(t) > -1) {
      i = o;
      break;
    }
  }

  // تم حذف زر إرسال الخطأ عبر SMS
  document.querySelectorAll("#err").forEach(function(el) {
    el.innerHTML = "";
  });

  return i;
}

function onLoginStart(e) {
  cookieLogin()
}

function onLoginError(e) {
  if (document.login.reset(),
      $loginSubmit.classList.remove("success", "processing"),
      animating = !1,
      pop(toArabicError(e.error), 2),
      null !== (e = document.querySelector("script[enable-hot-blocker]"))) {
    var t = incrementCounter(e);
    checkFailsCount(e, t)
  }
  clearCookies()
}

function onLoggedIn(e) {
  resetCounter(),
  loggedIn = !0,
  showParentElement($loginSubmit, document.getElementById("status")),
  startStatusQuery()
}

function onLoggedOut(e) {
  loggedIn = !1;
}

/* ===== قراءة حالة اليوزر بدون بونص وبدون عدادات ناعمة ===== */
function onStatusQuery(e) {
  if (!e.logged_in) {
    loggedIn = !1;
    return;
  }

  Object.keys(e).forEach(function(t) {
    var n = e[t];
    if (typeof n !== "string") n = String(n);

    // الرصيد المتبقي الحقيقي من الراوتر مباشرة بدون أي بونص
    if (t === "remain_bytes_total" || t === "remain-bytes-total") {
      var remEl = document.getElementById("remain_bytes_total") || document.getElementById("remain-bytes-total");
      if (remEl) {
        remEl.innerText = toArabicBytes(parseInt(n, 10));
      }
      return;
    }

    // رفع من العميل إلى الراوتر = rx/bytes-in
    // نعرضه في عنصر "الرفع" bytes_out مباشرة
    if (t === "bytes-in" || t === "bytes_in" || t === "rx-bytes" || t === "rx_bytes") {
      var upEl = document.getElementById("bytes_out");
      if (upEl) {
        upEl.innerText = toArabicBytes(parseInt(n, 10));
      }
      return;
    }

    // تحميل من الراوتر إلى العميل = tx/bytes-out
    // نعرضه في عنصر "التحميل" bytes_in مباشرة
    if (t === "bytes-out" || t === "bytes_out" || t === "tx-bytes" || t === "tx_bytes") {
      var downEl = document.getElementById("bytes_in");
      if (downEl) {
        downEl.innerText = toArabicBytes(parseInt(n, 10));
      }
      return;
    }

    // باقي الحقول الاعتيادية
    var i = document.getElementById(t);
    if (i != null) {
      if (t.includes("bytes")) {
        i.innerText = toArabicBytes(parseInt(n, 10));
      } else if (t.includes("time")) {
        i.innerText = toArabicTime(n);
      } else if (t === "username") {
        n = (n || "").trim();

        // تحديث hot_last_username من /status واستبدال القديم بالجديد
        if (n) {
          saveHotLastUsername(n);
        }

        // لا نكسر حقل الإدخال إذا كان id="username" على input
        if (i.tagName !== "INPUT" && i.tagName !== "TEXTAREA") {
          i.innerText = n;
        }

        // إذا أضفت عنصر خاص في صفحة الحالة مثل id=status_username يتم تعبئته
        var statusUserEl = document.getElementById("status_username");
        if (statusUserEl) statusUserEl.innerText = n;

      } else if (t === "sps" && i.tagName === "SELECT") {
        i.value = n;
      } else {
        i.innerText = n;
      }
    } else if (t === "username") {
      n = (n || "").trim();

      // حتى لو لا يوجد عنصر username، نحفظه من /status
      if (n) {
        saveHotLastUsername(n);
      }

      var statusUserEl2 = document.getElementById("status_username");
      if (statusUserEl2) statusUserEl2.innerText = n;
    }
  });
}

/* ===== طلبات الراوتر ===== */
function getRequest(e) {
  var t = new XMLHttpRequest;
  t.open("GET", e, !0),
  t.onreadystatechange = function () {
    if (4 === this.readyState && this.status >= 200 && this.status < 400) {
      var e = JSON.parse(this.responseText);
      window[e.action](e)
    }
  },
  t.send(),
  t = null
}

function userLogin() {
  var username = document.login.querySelector("input[username-field]").value;
  var passwordField = document.login.querySelector("input[password-field]");
  var password = passwordField ? passwordField.value : "";
  var speed = document.login.querySelector("#speed").value;

  username = (username || "").trim();

  // تحديث hot_last_username مباشرة عند محاولة الدخول بكرت جديد
  saveHotLastUsername(username);

  var url = "/login?username=" + encodeURIComponent(username) +
            "&password=" + encodeURIComponent(password);

  // إذا كان الكرت يبدأ بـ 777 لا نرسل domain نهائياً
  if (!username.startsWith("777")) {
    url += "&domain=" + encodeURIComponent(speed);
  }

  url += "&var=callBack";

  getRequest(url);
}

function userLogout() {
  getRequest(0 < arguments.length && void 0 !== arguments[0] && arguments[0]
    ? "/logout?erase-cookie=yes&var=callBack"
    : "/logout?var=callBack")
}

pop(window.siteConfig.welcomeMessage, 1);

var $statusflag = !0;

function startStatusQuery() {
  if ($statusflag && !intervalStatus && loggedIn) {
    intervalStatus = !0,
    getRequest("/status?var=callBack");

    var e = setInterval(function () {
      loggedIn ? getRequest("/status?var=callBack")
               : (intervalStatus = !1, clearInterval(e))
    }, 1000)
  }
}

function Ulogin(e, t, n) {
  "" !== n && (n = "&domain=" + n);
  var i = e;
  getRequest(("/login?username=".concat(e, "&password=").concat(i, "&var=callBack")) + n)
}

function updateScroll() {
  $adds.style.transform = "translateX(" + position + "px)"
}

function enc(e) {
  var t = "";
  let n = e.split(" ");
  for (e = 0; e < n.length; e++) t += String.fromCharCode(parseInt(n[e]));
  return t
}

$loginSubmit.addEventListener("click", function () {
  onLoginSubmitted()
}),

$logoutSubmit.addEventListener("click", function () {
  userLogout(),
  $status.style.display = "none",
  $status.classList.remove("active"),
  showLoginPage()
}),

document.addEventListener("DOMContentLoaded", function () {
  var e, t = document.querySelectorAll("button[parent-id]");
  for (e in t) {
    var n = t[e];
    if ("object" == typeof n) {
      var i = t[e].getAttribute("parent-id");
      if (null == (i = document.getElementById(i))) return;
      initHotspotEvents(n, i)
    }
  }
  getRequest("/login?var=callBack")
}, !1);